/**
 * Owns Trickster state construction, exact live reads and detached next-choice data.
 * Inputs are original role/history and legal pair IDs; outputs preserve existing validation,
 * copied choices and rejection order. This boundary never commits exile or frame authority.
 */
import type {
  TricksterChoice,
  TricksterState,
  TricksterReadState,
} from "@ai-werewolf-arena/game-contract";
import { types } from "node:util";
import { Camp, type RoleComponent } from "../../../../core";
export const TRICKSTER_ROLE = "trickster" as const;
export const TRICKSTER_POLICY = "awa_trickster_exile_v1" as const;
function field(value: unknown, key: PropertyKey): unknown {
  if (!value || typeof value !== "object" || types.isProxy(value)) return undefined;
  const d = Object.getOwnPropertyDescriptor(value, key);
  return d && "value" in d ? d.value : undefined;
}
function exact(value: unknown, keys: readonly string[]): boolean {
  if (!value || typeof value !== "object" || types.isProxy(value) || Array.isArray(value))
    return false;
  const descriptors = Object.getOwnPropertyDescriptors(value);
  return (
    Reflect.ownKeys(descriptors).length === keys.length &&
    keys.every((k) => descriptors[k] && "value" in descriptors[k]!)
  );
}
function integer(value: unknown): value is number {
  return (
    typeof value === "number" &&
    Number.isSafeInteger(value) &&
    value > 0 &&
    value < Number.MAX_SAFE_INTEGER
  );
}
function arrayItems(value: unknown): unknown[] | null {
  if (types.isProxy(value) || !Array.isArray(value)) return null;
  const length = field(value, "length");
  if (typeof length !== "number" || !Number.isSafeInteger(length) || length < 0) return null;
  const descriptors = Object.getOwnPropertyDescriptors(value);
  if (Reflect.ownKeys(descriptors).length !== length + 1) return null;
  const result: unknown[] = [];
  for (let i = 0; i < length; i++) {
    const d = descriptors[String(i)];
    if (!d || !("value" in d)) return null;
    result.push(d.value);
  }
  return result;
}
/** Validate without invoking user-owned accessors, iterators or array methods. */
export function getTricksterState(role: RoleComponent | undefined): TricksterReadState | undefined {
  if (field(role, "role") !== TRICKSTER_ROLE || field(role, "camp") !== Camp.Wolf) return undefined;
  const state = field(field(role, "privateState"), "trickster");
  if (!exact(state, ["policy", "history"])) return undefined;
  if (field(state, "policy") !== TRICKSTER_POLICY) return undefined;
  const history = arrayItems(field(state, "history"));
  if (!history) return undefined;
  let previous = 0;
  let previousPass = false;
  const used = new Set<number>();
  for (const entry of history) {
    if (!exact(entry, ["day", "pair"])) return undefined;
    const day = field(entry, "day"),
      rawPair = field(entry, "pair");
    if (!integer(day) || day <= previous) return undefined;
    if (rawPair === null && previousPass && day === previous + 1) return undefined;
    previous = day;
    previousPass = rawPair === null;
    if (rawPair === null) continue;
    const pair = arrayItems(rawPair);
    if (
      !pair ||
      pair.length !== 2 ||
      !integer(pair[0]) ||
      !integer(pair[1]) ||
      pair[0] >= pair[1] ||
      used.has(pair[0]) ||
      used.has(pair[1])
    )
      return undefined;
    used.add(pair[0]);
    used.add(pair[1]);
  }
  return state as TricksterReadState;
}
export function createTricksterState(): TricksterState {
  return { policy: TRICKSTER_POLICY, history: [] };
}
export function projectTricksterState(role: RoleComponent | undefined): TricksterState | undefined {
  const state = getTricksterState(role);
  if (!state) return undefined;
  const history: TricksterChoice[] = [];
  for (const row of arrayItems(field(state, "history"))!) {
    const rawPair = field(row, "pair");
    const values = rawPair === null ? null : arrayItems(rawPair)!;
    history.push({
      day: field(row, "day") as number,
      pair: values ? [values[0] as number, values[1] as number] : null,
    });
  }
  return {
    policy: TRICKSTER_POLICY,
    history,
  };
}

/** Return a detached next state; the caller commits only after authority/life validation. */
export function nextTricksterChoice(
  role: RoleComponent | undefined,
  day: number,
  pair: readonly [number, number] | null,
  legalIds: readonly number[],
): TricksterState {
  const state = projectTricksterState(role);
  if (!state || !integer(day) || day <= (state.history.at(-1)?.day ?? 0))
    throw new Error("trickster_choice_invalid");
  if (pair === null) {
    const last = state.history.at(-1);
    if (last?.pair === null && last.day === day - 1) throw new Error("trickster_consecutive_pass");
    return { ...state, history: [...state.history, { day, pair: null }] };
  }
  const values = arrayItems(pair);
  if (
    !values ||
    values.length !== 2 ||
    !integer(values[0]) ||
    !integer(values[1]) ||
    values[0] === values[1]
  )
    throw new Error("trickster_target_invalid");
  const used = new Set(state.history.flatMap((row) => row.pair ?? []));
  if (values.some((id) => used.has(id as number) || !legalIds.includes(id as number)))
    throw new Error("trickster_target_invalid");
  const a = values[0],
    b = values[1];
  return { ...state, history: [...state.history, { day, pair: a < b ? [a, b] : [b, a] }] };
}

/**
 * 负责 诡术师 的原资料、初始化与运行贡献装配，内建展示只登记语言中立的具体角色标识。
 * 输入为原板子参数、角色组件与请求上下文；输出为分别登记的资料、运行及展示贡献，工具、阶段、初始化和特权 mock 回调保留原引用与顺序。
 * 展示在实际调用时由角色捕获读取原状态并逐片段交纯展示所有者；本模块不授予租约、执行归档或复制状态。
 * 失败和关闭时仍遵守原机制权限与已付费前缀，不把文案当授权。
 */
import { nativeRolePresentation } from "../presentation-contribution";
import { ORDINARY_WOLF_CONTRIBUTIONS } from "../wolf/ability-ports";
import { z } from "zod";
import { roleName, text } from "@ai-werewolf-arena/game-text";
import { RuleError } from "@ai-werewolf-arena/game-contract";
import { Role, Camp, WinCondition, Phase } from "../../../../core/domain/identity";
import type { NativeRoleContributions } from "../contracts";
import { TRICKSTER_POLICY, createTricksterState, getTricksterState } from "./state";
import {
  tricksterChoicePending,
  tricksterChoiceTargets,
  tricksterMayPass,
  tricksterPackReady,
} from "./night_frame";
import { TRICKSTER_EXCHANGE_STAGE } from "./night_stages";
const parameters = z.strictObject({
  policy: z.literal(TRICKSTER_POLICY).default(TRICKSTER_POLICY),
});
export const TRICKSTER_ROLE_PROFILE: NativeRoleContributions = {
  metadata: {
    ...ORDINARY_WOLF_CONTRIBUTIONS.metadata,
    role: Role.Trickster,
    camp: Camp.Wolf,
    maxCount: 1,
    supportedWinConditions: [WinCondition.SlaughterSide],
    supportedBoardRoles: [
      Role.Wolf,
      Role.Villager,
      Role.Seer,
      Role.Witch,
      Role.Magician,
      Role.OrderPrince,
      Role.Trickster,
    ],
    label: roleName("trickster"),
    skillBrief: text("zh-CN", "role.trickster.brief"),
  },
  runtime: {
    ...ORDINARY_WOLF_CONTRIBUTIONS.runtime,
    wolfTeam: (role, world) => {
      const ready =
        !!getTricksterState(role)?.history.length && (!world || tricksterPackReady(world));
      return {
        recognizedByPack: ready,
        recognizes: ready ? "pack" : "none",
        canChat: ready,
        canVoteForKill: ready,
      };
    },
    init: (role) => {
      role.privateState.trickster = createTricksterState();
    },
    configuration: {
      schema: parameters,
      defaults: parameters.parse({}),
      apply: (config, value) => ({ ...config, trickster: parameters.parse(value) }),
      serialize: (config) => parameters.parse(config.trickster ?? {}),
    },
    toolSpecs: [
      ...(ORDINARY_WOLF_CONTRIBUTIONS.runtime.toolSpecs ?? []),
      {
        name: "swap_exile_targets",
        parameters: {
          type: "object",
          properties: {
            first_id: { type: ["integer", "null"], minimum: 1 },
            second_id: { type: ["integer", "null"], minimum: 1 },
            abstain: { type: "boolean" },
          },
          required: ["first_id", "second_id", "abstain"],
          additionalProperties: false,
        },
        argHint:
          'swap_exile_targets args: {"first_id":number|null,"second_id":number|null,"abstain":true|false}',
        userPromptHintKey: "action.swap_exile_targets.hint",
      },
    ],
    stageDirectives: [
      ...(ORDINARY_WOLF_CONTRIBUTIONS.runtime.stageDirectives ?? []),
      {
        match: (tools) => tools.length === 1 && tools[0] === "swap_exile_targets",
        messageKey: "action.swap_exile_targets.directive",
        text: text("zh-CN", "action.swap_exile_targets.directive"),
      },
    ],
    validationRules: {
      ...ORDINARY_WOLF_CONTRIBUTIONS.runtime.validationRules,
      swap_exile_targets: ({ world, role, actorId, day, phase, toolCall }) => {
        if (
          !getTricksterState(role) ||
          day === undefined ||
          phase !== Phase.Night ||
          toolCall.name !== "swap_exile_targets" ||
          !tricksterChoicePending(world, actorId, day)
        )
          return { code: RuleError.TricksterUnavailable };
        const { first_id, second_id, abstain } = toolCall.args;
        if (abstain)
          return first_id === null && second_id === null && tricksterMayPass(world, day)
            ? null
            : { code: RuleError.TricksterTarget };
        const targets = tricksterChoiceTargets(world, day);
        return first_id !== null &&
          second_id !== null &&
          first_id !== second_id &&
          targets.includes(first_id) &&
          targets.includes(second_id)
          ? null
          : { code: RuleError.TricksterTarget };
      },
    },
    nightStages: [TRICKSTER_EXCHANGE_STAGE, ...(ORDINARY_WOLF_CONTRIBUTIONS.runtime.nightStages ?? [])],
    baselineAction: (role, request, pick, pickCamp, locale, world) => {
      if (
        !request.allowedTools.includes("swap_exile_targets") ||
        !world ||
        !getTricksterState(role)
      )
        return (
          ORDINARY_WOLF_CONTRIBUTIONS.runtime.baselineAction?.(
            role,
            request,
            pick,
            pickCamp,
            locale,
            world,
          ) ?? null
        );
      const targets = tricksterChoiceTargets(world, request.context.day);
      return targets.length >= 2
        ? {
            name: "swap_exile_targets",
            args: { first_id: targets[0]!, second_id: targets[1]!, abstain: false },
          }
        : { name: "swap_exile_targets", args: { first_id: null, second_id: null, abstain: true } };
    },
  },
  presentation: nativeRolePresentation("trickster"),
};

/**
 * Owns Trickster exchange choices and exile substitution for the captured night. Inputs are
 * original bodies and the paired choice; outputs are exchange/cancel facts and the resolved
 * exile mapping. Finish or abort ends the exchange window without granting an old mapping to a
 * new life.
 */
import type { TricksterReadState } from "@ai-werewolf-arena/game-contract";
import { mapTricksterExileTarget } from "./exile_mapping";
import { types } from "node:util";
import { COMPONENT, type RoleComponent, type World } from "../../../../core";
import {
  aliveLifeDescriptor,
  aliveLifeVersion,
  type AliveComponent,
} from "../../../../core/domain/components/alive";
import {
  getTricksterState,
  projectTricksterState,
  TRICKSTER_ROLE,
  nextTricksterChoice,
} from "./state";

interface OriginalPlayer {
  id: number;
  role: RoleComponent;
  roleName: RoleComponent["role"];
  camp: RoleComponent["camp"];
  privateState: RoleComponent["privateState"];
  identity: unknown;
  seat: number;
  name: string;
  sessionId: string;
  life: AliveComponent;
  version: number;
}
interface ExchangeNight {
  day: number;
  closed: boolean;
  committed: boolean;
  finished: boolean;
  exileResolved: boolean;
  pair: readonly [number, number] | null;
  targets: ReadonlyMap<number, OriginalPlayer>;
}
interface Board {
  actorId: number;
  state: TricksterReadState;
  expectedState: string;
  players: ReadonlyMap<number, OriginalPlayer>;
  night: ExchangeNight | null;
}
const boards = new WeakMap<World, Board>();
function stateIdentity(role: RoleComponent): string {
  const view = projectTricksterState(role);
  if (!view) throw new Error("trickster_original_state_revoked");
  return JSON.stringify(view);
}
function ownData(value: unknown, key: PropertyKey): unknown {
  if (!value || typeof value !== "object" || types.isProxy(value)) return undefined;
  const d = Object.getOwnPropertyDescriptor(value, key);
  return d && "value" in d ? d.value : undefined;
}
function originalPlayer(world: World, p: OriginalPlayer): boolean {
  if (
    world.getComponent(p.id, COMPONENT.Role) !== p.role ||
    ownData(p.role, "role") !== p.roleName ||
    ownData(p.role, "camp") !== p.camp ||
    ownData(p.role, "privateState") !== p.privateState ||
    world.getComponent(p.id, COMPONENT.Identity) !== p.identity ||
    ownData(p.identity, "id") !== p.id ||
    ownData(p.identity, "seat") !== p.seat ||
    ownData(p.identity, "name") !== p.name ||
    ownData(p.identity, "sessionId") !== p.sessionId ||
    world.getComponent(p.id, COMPONENT.Alive) !== p.life
  )
    return false;
  const expected = aliveLifeDescriptor(p.life);
  const current = Object.getOwnPropertyDescriptor(p.life, "alive");
  if (
    !expected ||
    !current ||
    current.get !== expected.get ||
    current.set !== expected.set ||
    current.enumerable !== expected.enumerable ||
    current.configurable !== expected.configurable
  )
    return false;
  const version = aliveLifeVersion(p.life);
  // A committed exchange survives one ordinary death, never revival or another life.
  return p.life.alive ? version === p.version : version === p.version + 1;
}
function requireBoard(world: World): Board {
  const b = boards.get(world);
  if (!b) throw new Error("trickster_board_missing");
  const ids = world.entityIds();
  if (
    ids.length !== b.players.size ||
    ids.some((id) => !b.players.has(id)) ||
    [...b.players.values()].some((p) => !originalPlayer(world, p))
  )
    throw new Error("trickster_original_state_revoked");
  const actor = b.players.get(b.actorId)!;
  if (getTricksterState(actor.role) !== b.state || stateIdentity(actor.role) !== b.expectedState)
    throw new Error("trickster_original_state_revoked");
  return b;
}
export function installTricksterBoard(world: World): void {
  if (boards.has(world)) throw new Error("trickster_board_already_installed");
  const players = new Map<number, OriginalPlayer>();
  const seats = new Set<number>();
  let actorId: number | null = null;
  let state: TricksterReadState | undefined;
  for (const id of world.entityIds()) {
    const role = world.getComponent(id, COMPONENT.Role);
    const life = world.getComponent(id, COMPONENT.Alive);
    const version = life && aliveLifeVersion(life);
    if (!role || !life || types.isProxy(life) || version === undefined)
      throw new Error("trickster_original_roster_invalid");
    const expected = aliveLifeDescriptor(life);
    const descriptor = Object.getOwnPropertyDescriptor(life, "alive");
    if (
      !expected ||
      !descriptor ||
      expected.get !== descriptor.get ||
      expected.set !== descriptor.set ||
      expected.enumerable !== descriptor.enumerable ||
      expected.configurable !== descriptor.configurable ||
      !life.alive
    )
      throw new Error("trickster_original_roster_invalid");
    if (
      ownData(role, "role") === undefined ||
      ownData(role, "camp") === undefined ||
      ownData(role, "privateState") === undefined
    )
      throw new Error("trickster_original_roster_invalid");
    const identity = world.getComponent(id, COMPONENT.Identity);
    const seat = ownData(identity, "seat"),
      name = ownData(identity, "name"),
      sessionId = ownData(identity, "sessionId");
    if (
      ownData(identity, "id") !== id ||
      typeof seat !== "number" ||
      !Number.isSafeInteger(seat) ||
      seat <= 0 ||
      seats.has(seat) ||
      typeof name !== "string" ||
      typeof sessionId !== "string"
    )
      throw new Error("trickster_original_roster_invalid");
    seats.add(seat);
    players.set(id, {
      id,
      role,
      roleName: role.role,
      camp: role.camp,
      privateState: role.privateState,
      identity,
      seat,
      name,
      sessionId,
      life,
      version,
    });
    if (String(role.role) === TRICKSTER_ROLE) {
      if (actorId !== null) throw new Error("trickster_original_roster_invalid");
      actorId = id;
      state = getTricksterState(role);
    }
  }
  if (actorId === null || !state || state.history.length !== 0)
    throw new Error("trickster_original_roster_invalid");
  boards.set(world, {
    actorId,
    state,
    expectedState: stateIdentity(players.get(actorId)!.role),
    players,
    night: null,
  });
}
export function isTricksterBoard(world: World): boolean {
  if (!boards.has(world)) return false;
  requireBoard(world);
  return true;
}

export function beginTricksterNight(world: World, day: number): number | null {
  const b = requireBoard(world);
  if (
    !Number.isSafeInteger(day) ||
    day <= 0 ||
    day >= Number.MAX_SAFE_INTEGER ||
    (!b.night && day !== 1) ||
    (b.night && (!b.night.finished || day !== b.night.day + 1))
  )
    throw new Error("trickster_night_invalid");
  if (b.night) b.night.closed = true;
  const used = new Set(
    projectTricksterState(b.players.get(b.actorId)!.role)!.history.flatMap((row) => row.pair ?? []),
  );
  const targets = new Map([...b.players].filter(([id, p]) => p.life.alive && !used.has(id)));
  const eligible = b.players.get(b.actorId)!.life.alive && targets.size >= 2;
  b.night = {
    day,
    closed: false,
    committed: !eligible,
    finished: false,
    exileResolved: false,
    pair: null,
    targets,
  };
  return eligible ? b.actorId : null;
}
export function tricksterChoiceTargets(world: World, day: number): number[] {
  const b = requireBoard(world),
    n = b.night;
  if (!n || n.day !== day || n.closed || n.committed) return [];
  return [...n.targets.values()].filter((p) => p.life.alive).map((p) => p.id);
}
export function tricksterMayPass(world: World, day: number): boolean {
  const b = requireBoard(world),
    last = b.state.history.at(-1);
  return !(last?.pair === null && last.day === day - 1);
}
export function tricksterChoicePending(world: World, actorId: number, day: number): boolean {
  const b = requireBoard(world),
    n = b.night;
  return (
    b.actorId === actorId &&
    !!n &&
    n.day === day &&
    !n.closed &&
    !n.committed &&
    b.players.get(actorId)!.life.alive
  );
}
export function commitTricksterExchange(
  world: World,
  actorId: number,
  day: number,
  pair: readonly [number, number] | null,
): void {
  const b = requireBoard(world),
    n = b.night;
  if (!n || !tricksterChoicePending(world, actorId, day))
    throw new Error("trickster_choice_scope_invalid");
  const next = nextTricksterChoice(
    b.players.get(actorId)!.role,
    day,
    pair,
    tricksterChoiceTargets(world, day),
  );
  const choice = next.history.at(-1)!;
  Object.defineProperty(b.state.history, String(b.state.history.length), {
    value: choice,
    writable: true,
    enumerable: true,
    configurable: true,
  });
  b.expectedState = stateIdentity(b.players.get(actorId)!.role);
  n.pair = choice.pair && Object.freeze([choice.pair[0], choice.pair[1]] as [number, number]);
  n.committed = true;
}
export function cancelTricksterExchange(world: World, day: number): void {
  const b = requireBoard(world),
    n = b.night;
  if (!n || n.day !== day || n.closed || !n.committed || n.finished)
    throw new Error("trickster_night_unsettled");
  n.pair = null;
}
export function finishTricksterNight(world: World, day: number): void {
  const b = requireBoard(world),
    n = b.night;
  if (!n || n.day !== day || n.closed || !n.committed || n.finished)
    throw new Error("trickster_night_unsettled");
  n.finished = true;
}
export function resolveTricksterExile(
  world: World,
  day: number,
  requestedId: number,
): { requestedId: number; effectiveId: number; missed: boolean } {
  const b = requireBoard(world),
    n = b.night;
  if (!n || n.day !== day || n.closed || !n.committed || !n.finished || n.exileResolved)
    throw new Error("trickster_exile_unsettled");
  const original = b.players.get(requestedId);
  if (!original?.life.alive) throw new Error("trickster_target_invalid");
  const effectiveId = mapTricksterExileTarget(requestedId, n.pair)!;
  const effective = b.players.get(effectiveId);
  if (!effective) throw new Error("trickster_target_invalid");
  n.exileResolved = true;
  return { requestedId, effectiveId, missed: !effective.life.alive };
}
export function assertTricksterRosterCurrent(world: World): void {
  requireBoard(world);
}
export function abortTricksterNight(world: World): void {
  const n = boards.get(world)?.night;
  if (n && !n.finished) n.closed = true;
}

export function tricksterActorId(world: World): number {
  return requireBoard(world).actorId;
}

export function tricksterPackReady(world: World): boolean {
  return requireBoard(world).state.history.length > 0;
}

/**
 * Runs the Trickster paired-exchange request before subsequent night actions. Inputs are the
 * bound frame, policy pass allowance and validated choice; outputs preserve its exchange or
 * cancellation evidence. Exile substitution remains frame-owned and is not performed by the
 * provider.
 */
import { COMPONENT, type RoleComponent, type AliveComponent } from "../../../../core";
import { Phase } from "../../../../core/domain/identity";
import type { NightStageHandler } from "../../stages/night/contracts";
import { getTricksterState } from "./state";
import {
  assertTricksterRosterCurrent,
  beginTricksterNight,
  commitTricksterExchange,
  tricksterChoiceTargets,
  tricksterMayPass,
  tricksterActorId,
  cancelTricksterExchange,
} from "./night_frame";
import { cancelMagicianExchangeIfMatching } from "../magician/night_frame";
export const TRICKSTER_EXCHANGE_STAGE: NightStageHandler = {
  id: "trickster_exchange",
  priority: 100,
  async execute(ctx) {
    const day = ctx.currentDay(),
      actorId = beginTricksterNight(ctx.world, day);
    if (actorId === null) {
      const id = tricksterActorId(ctx.world);
      ctx.events.push({
        timestamp: Date.now(),
        type: "trickster_exchange_skipped",
        payload: {
          actorId: id,
          day,
          reason: ctx.world.getComponent(id, COMPONENT.Alive)!.alive ? "exhausted" : "dead",
        },
        audience: Object.freeze([id]),
      });
      return;
    }
    const role = ctx.world.getComponent(actorId, COMPONENT.Role);
    if (!getTricksterState(role)) throw new Error("trickster_actor_invalid");
    const request = ctx.makeRequest(actorId, ["swap_exile_targets"], {
      stage: "trickster_exchange",
      requiresAction: true,
      action_failure_policy: "error",
      allow_fallback: false,
      trickster_candidates: tricksterChoiceTargets(ctx.world, day),
      trickster_may_pass: tricksterMayPass(ctx.world, day),
    });
    assertTricksterRosterCurrent(ctx.world);
    const action = await ctx.actionProvider.getAction(request);
    assertTricksterRosterCurrent(ctx.world);
    if (!ctx.isCurrent() || ctx.currentDay() !== day) throw new Error("trickster_exchange_stale");
    if (action?.name !== "swap_exile_targets") throw new Error("trickster_exchange_action_missing");
    const validated = ctx.toolGateway.validateAndSanitize(ctx.world, actorId, action, {
      phase: Phase.Night,
      day,
    });
    assertTricksterRosterCurrent(ctx.world);
    if (!ctx.isCurrent() || ctx.currentDay() !== day) throw new Error("trickster_exchange_stale");
    if (!validated.ok || validated.sanitizedCall?.name !== "swap_exile_targets")
      throw new Error("trickster_exchange_action_invalid");
    const args = validated.sanitizedCall.args,
      pair: [number, number] | null = args.abstain ? null : [args.first_id!, args.second_id!];
    commitTricksterExchange(ctx.world, actorId, day, pair);
    ctx.events.push({
      timestamp: Date.now(),
      type: "trickster_exchange_committed",
      payload: { actorId, day, pair: pair && [Math.min(...pair), Math.max(...pair)] },
      audience: Object.freeze([actorId]),
    });
    if (pair && cancelMagicianExchangeIfMatching(ctx.world, day, pair))
      cancelTricksterExchange(ctx.world, day);
  },
};

